let out=defs+`<rect width="960" height="540" fill="url(#cinemaSky)"/><g class="parallax-far"><circle cx="770" cy="83" r="111" fill="url(#sunGlow)"/><circle class="movie-sun" cx="770" cy="83" r="37" fill="${night?'#fff0c0':'#f8d48e'}"/>${night?'<g class="sky-stars" fill="#fff3d0"><circle cx="320" cy="58" r="2"/><circle cx="480" cy="92" r="2.5"/><circle cx="580" cy="43" r="2"/><circle cx="130" cy="130" r="2"/></g>':''}<g class="clouds" fill="#fff9e9" opacity=".75"><path d="M94 105q-21-26 10-35 7-31 37-18 19-26 44-1 33-7 36 22 31 20-5 32Z"/><path d="M387 122q-11-20 11-25 15-32 39-10 24-7 28 11 36 10 11 24Z"/></g><path d="M-100 257 102 143 263 242 455 144 650 231 863 135 1060 233V540H-100" fill="#a8c7b2" opacity=".7"/><path d="M-100 273Q125 174 326 250T1080 207V540H-100" fill="#a6c5a4"/></g><g class="parallax-mid"><path d="M-90 300Q180 212 415 286T1040 253V540H-90Z" fill="#8eae87"/>${[160,360,600,825].map((x,i)=>`<g transform="translate(${x} ${258+i%2*14}) scale(.35)">${richTree(0,0,1,1)}</g>`).join('')}<path d="M-100 359Q180 273 465 324T1070 290V540H-100Z" fill="url(#cinemaGround)"/></g>`;
